<?php get_header();the_post();$id=get_the_ID();$price=litano_price($id); ?><main class="litano-section"><div class="litano-container product-single"><div class="product-gallery"><?php if(has_post_thumbnail())the_post_thumbnail('large');else echo '<div class="litano-placeholder large">LITANO</div>'; ?></div><div class="product-info"><div class="litano-eyebrow"><?php echo esc_html(get_post_meta($id,'_litano_metal',true)); ?></div><h1><?php the_title(); ?></h1><div class="single-price"><?php echo esc_html(litano_money($price)); ?></div><div class="spec-table"><?php foreach(['weight'=>'Weight','purity'=>'Purity / Fineness','refinery'=>'Refinery / Mint','origin'=>'Origin','sku'=>'Product Code','status'=>'Availability','premium'=>'Premium','shipping'=>'Shipping'] as $k=>$label){$v=get_post_meta($id,'_litano_'.$k,true);if($v)echo '<div><span>'.esc_html($label).'</span><strong>'.esc_html($v).'</strong></div>';} ?></div><button class="litano-primary-btn litano-add-cart" data-id="<?php echo $id; ?>" data-name="<?php echo esc_attr(get_the_title()); ?>" data-price="<?php echo esc_attr($price); ?>">Add to Cart</button><div class="product-copy"><?php the_content(); ?></div><p class="litano-notice">Final price, availability, applicable taxes and shipping are confirmed before settlement.</p></div></div></main><?php get_footer(); ?>
